('watchdog.consumer.sale_context_strength','watchdog-cohort-v1','40% peer sale coverage + 30% peer sale recency + 30% inverse peer sale dispersion',array['cohort.sale_sample_coverage_score','cohort.sale_recency_score','cohort.sale_price_dispersion_score']::text[],'medium','live','Cohort-aware public sale context using observed peer record coverage, five-year recency and inverse relative IQR dispersion; not a valuation opinion.','weighted_scores',jsonb_build_object('items',jsonb_build_array(jsonb_build_object('dep','cohort.sale_sample_coverage_score','weight',40,'transform','identity'),jsonb_build_object('dep','cohort.sale_recency_score','weight',30,'transform','identity'),jsonb_build_object('dep','cohort.sale_price_dispersion_score','weight',30,'transform','inverse')),'require_all',true),now()),
